import{_ as t,o as s,c as a,ao as o}from"./chunks/framework.B7UvRKha.js";const g=JSON.parse('{"title":"Configuration Files","description":"","frontmatter":{},"headers":[],"relativePath":"ref/config.md","filePath":"ref/config.md","lastUpdated":null}'),i={name:"ref/config.md"};function n(l,e,r,d,h,c){return s(),a("div",null,[...e[0]||(e[0]=[o(`<h1 id="Configuration-Files" tabindex="-1">Configuration Files <a class="header-anchor" href="#Configuration-Files" aria-label="Permalink to &quot;Configuration Files {#Configuration-Files}&quot;">​</a></h1><p>Five TOML files, each with one reader and none read by more than one parser: <code>settings.toml</code> (layout + terminal, read by the frontend, first file found wins), <code>hosts.toml</code> (the declared topology — hub, daemon and frontend hosts, monitor targets — read ONLY by <code>sot_topology</code>/<code>sotd topology</code>; the frontend reads no config file for hosts at all, see below), <code>keybindings.toml</code> (chords, read by the frontend, same discovery), and the project chat&#39;s <code>chat.toml</code> and <code>chat-secrets.toml</code> (read by the hub&#39;s daemon). Keybindings have their own page — <a href="./keybindings">Keybindings</a> — so this page covers the other four.</p><p><code>settings.toml</code> and <code>keybindings.toml</code> share one discovery pattern: the frontend reads the first file it finds among an env-var path, a <code>.sot/</code> file found by walking up from the frontend&#39;s working directory, and a per-user file, and never reads the others; built-in defaults fill anything the file leaves out. Missing or out-of-range values fall back to the default rather than crashing the chrome. <code>hosts.toml</code> has its own, simpler search order — see below.</p><h2 id="settings.toml" tabindex="-1"><code>settings.toml</code> <a class="header-anchor" href="#settings.toml" aria-label="Permalink to &quot;\`settings.toml\` {#settings.toml}&quot;">​</a></h2><p>Frontend settings.</p><h3 id="Discovery-order" tabindex="-1">Discovery order <a class="header-anchor" href="#Discovery-order" aria-label="Permalink to &quot;Discovery order {#Discovery-order}&quot;">​</a></h3><ol><li><p><code>$SOT_SETTINGS</code> — explicit path override.</p></li><li><p><code>.sot/settings.toml</code>, found by walking upward from the frontend&#39;s working directory (not the session&#39;s project).</p></li><li><p><code>$HOME/.config/sot/settings.toml</code> — per-user settings.</p></li><li><p>Built-in defaults.</p></li></ol><p>Any value that is missing or out of range silently falls back to its default — the chrome never crashes on a malformed settings file.</p><h3 id="layout" tabindex="-1"><code>[layout]</code> <a class="header-anchor" href="#layout" aria-label="Permalink to &quot;\`[layout]\` {#layout}&quot;">​</a></h3><p>Layout is <strong>preset-based</strong>, keyed by the primary monitor&#39;s aspect ratio — there is no in-session reflow. The top-level <code>[layout]</code> table selects the active preset; three sub-tables define the presets.</p><table tabindex="0"><thead><tr><th style="text-align:right;">Key</th><th style="text-align:right;">Type</th><th style="text-align:right;">Values</th><th style="text-align:right;">Default</th><th style="text-align:right;">Meaning</th></tr></thead><tbody><tr><td style="text-align:right;"><code>preset</code></td><td style="text-align:right;">string</td><td style="text-align:right;"><code>auto</code> · <code>ultrawide</code> · <code>laptop</code> · <code>portrait</code></td><td style="text-align:right;"><code>auto</code></td><td style="text-align:right;">Which preset to use. <code>auto</code> resolves by the primary monitor&#39;s aspect ratio at startup (<code>&gt; 1.9</code> → ultrawide, <code>1.5–1.9</code> → laptop, <code>&lt; 1.5</code> → portrait); the other three lock to that preset regardless of aspect.</td></tr></tbody></table><h4 id="layout.ultrawide-/-layout.laptop-/-layout.portrait" tabindex="-1"><code>[layout.ultrawide]</code> / <code>[layout.laptop]</code> / <code>[layout.portrait]</code> <a class="header-anchor" href="#layout.ultrawide-/-layout.laptop-/-layout.portrait" aria-label="Permalink to &quot;\`[layout.ultrawide]\` / \`[layout.laptop]\` / \`[layout.portrait]\` {#layout.ultrawide-/-layout.laptop-/-layout.portrait}&quot;">​</a></h4><p>One sub-table per aspect bucket, each defining its columns, their widths, and the shared bottom drawer.</p><table tabindex="0"><thead><tr><th style="text-align:right;">Key</th><th style="text-align:right;">Type</th><th style="text-align:right;">Default (ultrawide)</th><th style="text-align:right;">Meaning</th></tr></thead><tbody><tr><td style="text-align:right;"><code>columns</code></td><td style="text-align:right;">comma-list of slot names (<code>nav</code> · <code>preview</code> · <code>llm</code> · <code>repl</code>)</td><td style="text-align:right;"><code>nav,preview,llm</code></td><td style="text-align:right;">Named column slots, left to right.</td></tr><tr><td style="text-align:right;"><code>widths</code></td><td style="text-align:right;">comma-list of fractions</td><td style="text-align:right;"><code>0.167,0.333,0.5</code></td><td style="text-align:right;">Fractional column widths, one per column; renormalized to sum to 1.0 on parse. A count that differs from <code>columns</code> warns and gives the columns an equal split.</td></tr><tr><td style="text-align:right;"><code>drawer</code></td><td style="text-align:right;">slot name or <code>none</code></td><td style="text-align:right;"><code>repl</code></td><td style="text-align:right;">Slot rendered in the shared bottom drawer when toggled open.</td></tr><tr><td style="text-align:right;"><code>drawer_height</code></td><td style="text-align:right;">fraction <code>[0.10, 0.80]</code></td><td style="text-align:right;"><code>0.35</code></td><td style="text-align:right;">Drawer height as a fraction of window height when open; clamped to range.</td></tr></tbody></table><p>Laptop defaults to <code>0.18,0.32,0.50</code> widths with a <code>0.40</code> drawer; portrait drops the <code>llm</code> column (<code>nav,preview</code> at <code>0.30,0.70</code>, <code>0.40</code> drawer). Unknown keys and out-of-range values warn and fall back to the default.</p><h3 id="Other-sections" tabindex="-1">Other sections <a class="header-anchor" href="#Other-sections" aria-label="Permalink to &quot;Other sections {#Other-sections}&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:right;">Section / key</th><th style="text-align:right;">Type</th><th style="text-align:right;">Default</th><th style="text-align:right;">Meaning</th></tr></thead><tbody><tr><td style="text-align:right;"><code>[terminal] shell</code></td><td style="text-align:right;">string</td><td style="text-align:right;"><em>(auto)</em></td><td style="text-align:right;">Shell the Terminal drawer spawns. Unset resolves per platform: <code>$SHELL</code>, then <code>/bin/bash</code>, <code>/bin/sh</code> on Unix; <code>pwsh.exe</code>, <code>powershell.exe</code>, <code>cmd.exe</code> on Windows.</td></tr><tr><td style="text-align:right;"><code>[downloads] dir</code></td><td style="text-align:right;">path</td><td style="text-align:right;"><em>(OS download dir)</em></td><td style="text-align:right;">Local directory <code>d</code> (download) writes to. Empty means the OS download directory.</td></tr><tr><td style="text-align:right;"><code>[chat] name</code></td><td style="text-align:right;">string</td><td style="text-align:right;"><em>(unset)</em></td><td style="text-align:right;">The author a chat post carries beside the app&#39;s name. Unset or blank, the Chat drawer does not post.</td></tr><tr><td style="text-align:right;"><code>[sessions] new_session_root</code></td><td style="text-align:right;">path</td><td style="text-align:right;"><em>(fallback chain)</em></td><td style="text-align:right;">Backend-host directory the new-session picker starts browsing from. Unset falls back to <code>$SOT_PROJECTS_ROOT</code>, <code>$SOT_REMOTE_HOME</code>, the daemon&#39;s default root, then <code>$HOME</code>.</td></tr></tbody></table><h3 id="gpu" tabindex="-1"><code>[gpu]</code> <a class="header-anchor" href="#gpu" aria-label="Permalink to &quot;\`[gpu]\` {#gpu}&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:right;">Key</th><th style="text-align:right;">Type</th><th style="text-align:right;">Values</th><th style="text-align:right;">Default</th><th style="text-align:right;">Meaning</th></tr></thead><tbody><tr><td style="text-align:right;"><code>power_preference</code></td><td style="text-align:right;">string</td><td style="text-align:right;"><code>low</code> · <code>high</code></td><td style="text-align:right;"><code>low</code></td><td style="text-align:right;">Which adapter to request from wgpu. <code>low</code> prefers the integrated GPU; <code>high</code> prefers the discrete one. wgpu&#39;s own spellings (<code>low_power</code>, <code>high_performance</code>) and <code>integrated</code>/<code>discrete</code> are accepted; case is ignored.</td></tr></tbody></table><p>The frontend renders glyph quads and image blits — a 2D workload an integrated GPU handles comfortably — so it asks for the <strong>low-power adapter by default</strong>. On a hybrid-graphics laptop, requesting the discrete GPU keeps it awake for the entire session (measured ~11 W on an otherwise idle RTX 4070): an active surface prevents the dGPU from power-gating. Set <code>high</code> if you are on a desktop with a real GPU, or if the integrated adapter renders incorrectly.</p><p>On single-adapter machines the key is a <strong>no-op</strong> — with only an integrated GPU present, <code>high</code> already resolves to it.</p><blockquote><p><strong>Takes effect on the next frontend start.</strong> The preference binds once, when the adapter and surface are created at startup, so editing this key mid-session changes nothing until the frontend restarts.</p></blockquote><h3 id="display" tabindex="-1"><code>[display]</code> <a class="header-anchor" href="#display" aria-label="Permalink to &quot;\`[display]\` {#display}&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:right;">Key</th><th style="text-align:right;">Type</th><th style="text-align:right;">Default</th><th style="text-align:right;">Meaning</th></tr></thead><tbody><tr><td style="text-align:right;"><code>fullscreen_vsync_pin</code></td><td style="text-align:right;">bool</td><td style="text-align:right;"><code>false</code></td><td style="text-align:right;">While fullscreen, keep requesting a redraw every vsync instead of falling back to the on-demand idle tick.</td></tr></tbody></table><p>In borderless fullscreen, DWM composition disengages and the panel&#39;s refresh follows the frontend&#39;s present cadence directly. The efficient on-demand idle path presents ~1 frame/sec, which drives a VRR/adaptive-sync OLED panel into the 1–10 Hz band where low-framerate compensation makes brightness pump visibly. With the pin on, fullscreen instead requests a redraw every vsync so the panel stays pinned at its native refresh; this costs continuous GPU while fullscreen.</p><p>There is no VRR/adaptive-sync detection API worth trusting, so this is a setting rather than a heuristic, and it defaults to <code>false</code>: most panels are fixed-refresh and the pin only burns power for no visible benefit — measured 25.5 points of one core and 8.5 points of iGPU 3D continuously at idle in fullscreen (measured on one laptop). Set <code>true</code> on a VRR/adaptive-sync OLED panel that pumps brightness in borderless fullscreen.</p><h3 id="Example" tabindex="-1">Example <a class="header-anchor" href="#Example" aria-label="Permalink to &quot;Example {#Example}&quot;">​</a></h3><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">layout</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">preset = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;auto&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # auto | ultrawide | laptop | portrait</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">layout</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ultrawide</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]              </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># primary monitor aspect &gt; 1.9</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">columns       = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;nav,preview,llm&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">widths        = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;0.167,0.333,0.5&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">drawer        = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;repl&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">drawer_height = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;0.35&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gpu</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">power_preference = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;low&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # low (integrated, default) | high (discrete)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">display</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">fullscreen_vsync_pin = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # default false | true on a VRR/OLED panel</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chat</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">name = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Ada&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                    # the author a chat post carries; quote it</span></span></code></pre></div><h2 id="hosts.toml" tabindex="-1"><code>hosts.toml</code> <a class="header-anchor" href="#hosts.toml" aria-label="Permalink to &quot;\`hosts.toml\` {#hosts.toml}&quot;">​</a></h2><p>The declared topology: which host is the relay hub, which hosts run a daemon, which run a frontend, and which hosts a <code>Ctrl+M</code> monitor drawer samples. <code>sot_topology</code> (Rust) is the <strong>one parser</strong> for this file — the daemon&#39;s <code>sotd topology plan|status|sync|relay-endpoint</code> CLI is the one way anything reads it. Neither the frontend nor the PowerShell launcher parses <code>hosts.toml</code> itself any more: the launcher runs <code>sotd topology plan --self &lt;host&gt;</code> and renders its plain-line output into <code>--dial &lt;host&gt;=&lt;endpoint&gt;</code> flags for the frontend (each a link the frontend starts itself over one ssh login, or a local socket/pipe); the frontend reads no config file for hosts at all (see <code>--dial</code> under <a href="./../start/setup">CLI flags</a>, and <code>rust/topology/src/lib.rs</code>&#39;s <code>plan</code> doc comment for the exact line-oriented contract).</p><p>The format is deliberately simple — a section per host, scalar <code>key = value</code> lines — so it needs no TOML library. Values pass through <strong>verbatim</strong>: there is no TOML escape processing, so Windows pipe paths use single backslashes.</p><h3 id="Discovery-order-2" tabindex="-1">Discovery order <a class="header-anchor" href="#Discovery-order-2" aria-label="Permalink to &quot;Discovery order {#Discovery-order-2}&quot;">​</a></h3><p>The one search order, used everywhere this file is read:</p><ol><li><p><code>$SOT_HOSTS</code> — explicit path override (tests, scratch daemons).</p></li><li><p><code>&lt;config dir&gt;/hosts.toml</code> — <code>~/.config/sot/hosts.toml</code> on Linux/macOS, <code>%LOCALAPPDATA%\\sot\\config\\hosts.toml</code> on Windows.</p></li></ol><p>There is no repo-local <code>.sot/hosts.toml</code> layer any more: the hub&#39;s own copy is canonical, and every other box&#39;s copy is a <code>sotd topology sync --hub &lt;alias&gt;</code> fetch of it (see below).</p><h3 id="Top-level" tabindex="-1">Top-level <a class="header-anchor" href="#Top-level" aria-label="Permalink to &quot;Top-level {#Top-level}&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:right;">Key</th><th style="text-align:right;">Type</th><th style="text-align:right;">Default</th><th style="text-align:right;">Meaning</th></tr></thead><tbody><tr><td style="text-align:right;"><code>hub</code></td><td style="text-align:right;">string</td><td style="text-align:right;"><em>(required)</em></td><td style="text-align:right;">The one host running the relay daemon every other box&#39;s comm handles register on and dial through. Exactly one <code>hub</code> key, naming a listed host.</td></tr></tbody></table><h3 id="host.name" tabindex="-1"><code>[host.&lt;name&gt;]</code> <a class="header-anchor" href="#host.name" aria-label="Permalink to &quot;\`[host.&lt;name&gt;]\` {#host.name}&quot;">​</a></h3><p>One section per host. <code>&lt;name&gt;</code> is the plain host name (<code>[a-z0-9][a-z0-9._-]*</code>) that box&#39;s own <code>host_name()</code> resolves to — it doubles as its SSH alias. Every other box reaches a daemon host through one ssh login into the hub, so only the hub needs an <code>~/.ssh/config</code> entry for each daemon host, and every other box needs one for the hub.</p><table tabindex="0"><thead><tr><th style="text-align:right;">Key</th><th style="text-align:right;">Type</th><th style="text-align:right;">Default</th><th style="text-align:right;">Meaning</th></tr></thead><tbody><tr><td style="text-align:right;"><code>daemon</code></td><td style="text-align:right;">bool</td><td style="text-align:right;"><code>false</code></td><td style="text-align:right;">This host runs <code>sotd</code> and can be dialled. <code>sotd topology plan</code> emits a <code>dial</code> line for every daemon host: this box&#39;s own socket for itself, the hub&#39;s own relay socket for a remote host (on the hub only), and <code>ssh:&lt;hub&gt;</code> / <code>ssh:&lt;hub&gt;/&lt;host&gt;</code> everywhere else.</td></tr><tr><td style="text-align:right;"><code>frontend</code></td><td style="text-align:right;">bool</td><td style="text-align:right;"><code>false</code></td><td style="text-align:right;">This host runs a frontend and its launcher.</td></tr></tbody></table><p>A host can be <code>daemon = true</code>, <code>frontend = true</code>, neither (the section is otherwise pointless), or both (a workstation running its own daemon <em>and</em> driving a local frontend). The hub itself needs <code>daemon = true</code> too — it is still a listed host, just the one every other daemon host&#39;s relay handles register on.</p><h3 id="File-watcher-budget" tabindex="-1">File-watcher budget <a class="header-anchor" href="#File-watcher-budget" aria-label="Permalink to &quot;File-watcher budget {#File-watcher-budget}&quot;">​</a></h3><p><code>sotd</code> watches each workspace&#39;s tree to refresh previews on disk changes, registering one (non-recursive) inotify watch per kept directory. It skips build/VCS directories and never crosses a filesystem boundary (so a project root over a mounted data share doesn&#39;t pull the share in), and it caps the watches per workspace at <code>min(8192, ¼ of fs.inotify.max_user_watches)</code> so it can&#39;t exhaust the OS watch table. Override the cap with <code>SOT_WATCH_BUDGET=&lt;n&gt;</code> in the backend environment. Past the cap, deeper subtrees stop auto-refreshing; navigation still refreshes previews reactively.</p><h3 id="monitor" tabindex="-1"><code>[monitor]</code> <a class="header-anchor" href="#monitor" aria-label="Permalink to &quot;\`[monitor]\` {#monitor}&quot;">​</a></h3><p>The hosts sampled for the <code>Ctrl+M</code> server-monitor drawer. <strong>Hub-scoped:</strong> declared once, but only the declared <code>hub</code> executes it — every non-hub daemon samples just the host it runs on, regardless of what this table says, so the roster&#39;s ssh aliases need only resolve <strong>on the hub</strong>. The drawer itself subscribes to the hub, not to whichever host the frontend happens to be navigating. Each line is <code>&lt;display-name&gt; = &quot;&lt;ssh-alias&gt;&quot;</code>.</p><table tabindex="0"><thead><tr><th style="text-align:right;">Form</th><th style="text-align:right;">Meaning</th></tr></thead><tbody><tr><td style="text-align:right;"><code>&lt;name&gt; = &quot;&lt;ssh-alias&gt;&quot;</code></td><td style="text-align:right;">Sample this host in the monitor drawer. The host whose name (or alias) matches the hub&#39;s hostname is sampled <strong>locally</strong> (no SSH); the rest are sampled over <code>ssh &lt;alias&gt;</code> from the hub.</td></tr></tbody></table><p><code>nvidia-smi</code> and <code>/proc</code> are world-readable, so no <code>sudo</code> or special privileges are needed on any monitored host. Remove a line to stop monitoring that host. The sampler reads <code>/proc</code>, so a daemon samples its own host only on Linux; on macOS and Windows the local host is left out of the drawer.</p><h3 id="Example-2" tabindex="-1">Example <a class="header-anchor" href="#Example-2" aria-label="Permalink to &quot;Example {#Example-2}&quot;">​</a></h3><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">hub = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;myserver&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">host</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">myserver</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">daemon = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># A frontend box.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">host</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">laptop</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">frontend = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># A second daemon host; its SSH alias on the hub is \`otherbox\`.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">host</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">otherbox</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">daemon = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">monitor</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">myserver = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;myserver&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">otherbox = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;otherbox&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">host-c = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;host-c&quot;</span></span></code></pre></div><p><code>sotd topology plan --self laptop</code> on the laptop above renders as (see <code>rust/topology/src/lib.rs</code>&#39;s <code>plan</code> doc comment for the exact grammar):</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>self laptop</span></span>
<span class="line"><span>hub myserver</span></span>
<span class="line"><span>relay-endpoint ssh:myserver</span></span>
<span class="line"><span>dial myserver ssh:myserver</span></span>
<span class="line"><span>dial otherbox ssh:myserver/otherbox</span></span></code></pre></div><p>— which the launcher turns into <code>--dial myserver=ssh:myserver --dial otherbox=ssh:myserver/otherbox</code> for the frontend: one ssh login into the hub per host, no argument for the hub&#39;s own daemon and <code>--host otherbox</code> to reach the hub&#39;s relay socket for the other one. No port, no forward — read the actual endpoints from <code>sotd topology plan</code>, never hardcode one.</p><h2 id="chat.toml-and-chat-secrets.toml" tabindex="-1"><code>chat.toml</code> and <code>chat-secrets.toml</code> <a class="header-anchor" href="#chat.toml-and-chat-secrets.toml" aria-label="Permalink to &quot;\`chat.toml\` and \`chat-secrets.toml\` {#chat.toml-and-chat-secrets.toml}&quot;">​</a></h2><p>The project chat&#39;s configuration, two TOML files in the config folder (<code>~/.config/sot</code> on Linux and macOS, <code>%LOCALAPPDATA%\\sot\\config</code> on Windows).</p><p><em>Status: the daemon reads both files and connects to Slack with the two tokens. The Chat drawer shows the channel&#39;s held messages (see <a href="./../guide/chat">The project chat</a>), and a person&#39;s post goes out under <code>[chat] name</code> of <code>settings.toml</code>; mail is not built.</em></p><p>Only the hub&#39;s daemon reads them: the chat runs on the computer that <code>hosts.toml</code> (above) parses and names, by <code>SOT_SELF_HOST</code> or its host name, as its <code>hub</code>. A computer with no <code>hosts.toml</code>, or another computer, runs no chat and opens neither file. Both files are read once, when the daemon starts, and a mapped folder must have a row by then. After editing either file, or adding a row for a mapped folder, restart the daemon (on Linux <code>systemctl --user restart sotd</code>; rows keep running). A missing or refused <code>chat.toml</code>, or a missing or refused <code>chat-secrets.toml</code>, leaves the chat off. One refused mapping, such as a folder with no row at start, turns the chat off for every project. The reason is in the daemon&#39;s log, on the &quot;project chat&quot; line, as a fixed explanation with the mapping&#39;s number or the line, never a key&#39;s value; <code>sotd log-path</code> prints the log&#39;s path. A start that Slack refuses or cannot reach (a rejected token, no network) is logged as &quot;project chat did not start&quot; and stays failed until the daemon restarts.</p><p>Each file is a regular file of at most 64 KiB, and only the keys below are accepted.</p><p><code>chat.toml</code>:</p><table tabindex="0"><thead><tr><th style="text-align:right;">Key</th><th style="text-align:right;">Form</th><th style="text-align:right;">Required</th><th style="text-align:right;">Meaning</th></tr></thead><tbody><tr><td style="text-align:right;"><code>workspace</code></td><td style="text-align:right;">Slack id (a capital letter, then capitals and digits, 32 at most), not a name</td><td style="text-align:right;">yes</td><td style="text-align:right;">The one Slack workspace; it must equal <code>chat-secrets.toml</code>&#39;s. A list or table naming a second one is refused.</td></tr><tr><td style="text-align:right;"><code>channels</code></td><td style="text-align:right;">list of Slack ids</td><td style="text-align:right;">yes</td><td style="text-align:right;">The channels the chat may use. A repeated channel is refused.</td></tr><tr><td style="text-align:right;"><code>[[mapping]]</code></td><td style="text-align:right;">table</td><td style="text-align:right;">one per project</td><td style="text-align:right;"><code>folder</code>, an absolute path of a folder a row had when the daemon started (not the window&#39;s default row, which runs no agent), and <code>channel</code>, one of <code>channels</code>. On Windows write the path in single quotes (<code>&#39;C:\\work\\proj&#39;</code>). A table may also repeat <code>workspace</code>, which must match. Two entries for one folder, or one channel for two folders, are refused.</td></tr><tr><td style="text-align:right;"><code>mail_after</code></td><td style="text-align:right;">Slack timestamp (<code>&lt;seconds&gt;.&lt;six digits&gt;</code>), a quoted string</td><td style="text-align:right;">no</td><td style="text-align:right;">Read and checked; nothing uses it yet. <em>Mail delivery is unbuilt.</em></td></tr></tbody></table><p><code>chat-secrets.toml</code> holds <code>workspace</code>, <code>bot_token</code> (it starts <code>xoxb-</code>) and <code>app_token</code> (it starts <code>xapp-</code>), each token letters, digits and hyphens up to 512 bytes. Keep the file private to your account; the daemon never prints a token and masks one in its log, but it does not check the file&#39;s permissions.</p><h2 id="See-also" tabindex="-1">See also <a class="header-anchor" href="#See-also" aria-label="Permalink to &quot;See also {#See-also}&quot;">​</a></h2><ul><li><a href="./keybindings">Keybindings</a> — chords and grammar (still repo-local, under <code>.sot/</code>).</li></ul>`,62)])])}const y=t(i,[["render",n]]);export{g as __pageData,y as default};
